--  WHERE TABLE_NAME IN ('PRODUCT','WALLET','CONVERSATION','PRICE_OFFER','PURCHASE_ORDER',
--                       'SHIPMENT','REFUND_REQUEST','CHAT_MESSAGE','BALANCE_TRANSACTION')
--  ORDER BY TABLE_NAME;

COMMIT;
